/**
 * Fuzz of `parse.ts#parseValue`, called directly. Lot 2 of the PDF fuzz design (16/11/2026).
 * Input: values generated by fast-check, references included, spelled by a test writer made from ISO 32000-1:2008
 * (§7.2 lexical conventions, §7.3 objects: `pdf-syntax-writer.test.support.ts`) with random choices: octal escapes,
 * hex strings, `#xx` in names, comments, white-space variants, number forms. Each value is read at an offset, after
 * arbitrary bytes, and is followed by a separator, a delimiter and arbitrary bytes.
 * Properties: the value read equals the model's (round trip), and ends where the writer ended it; the node count
 * equals the generator's; the same bytes cut short or with bytes overwritten give a value or a refusal of ours, never a
 * raw error.
 *
 * The seed is fixed (`PDF_FUZZ_SEED`): a red run replays as is. The run counts are the written ones, times the weekly
 * multiplier (`lib/pdf-fuzz-runs.test.support.ts`).
 * NOT covered: indirect objects and streams (`parseIndirectObject`), damaged values (lot 0 reaches them through files).
 */

import fc from "fast-check";
import { describe, expect, it, vi } from "vitest";

import { parseValue } from "./parse";
import { PdfObjectsRefusal } from "./refusal";
import {
  Choices,
  drawsArb,
  expectedValue,
  separator,
  valueArb,
  valueNodes,
  type ValueModel,
  writeValue,
} from "./pdf-syntax-writer.test.support";
import { PDF_FUZZ_SEED } from "../pdf-fuzz-outcome.test.support";
import { fuzzRuns, fuzzTestTimeout } from "../../lib/pdf-fuzz-runs.test.support";

vi.setConfig({ testTimeout: fuzzTestTimeout(20000, process.env) });

const params = (baseRuns: number): fc.Parameters<unknown> => ({
  numRuns: fuzzRuns(baseRuns, process.env),
  seed: PDF_FUZZ_SEED,
  timeout: 8000,
});

const latin1 = (text: string): Uint8Array => Uint8Array.from(text, (char) => char.charCodeAt(0));

interface Written {
  readonly bytes: Uint8Array;
  readonly offset: number;
  /** Where the value ends: just past its last byte. */
  readonly end: number;
}

/** Arbitrary bytes, the value at `offset` after a separator or none, then a separator or none, `)` and arbitrary bytes.
 *  The `)` ends a number and stops the lookahead of a reference (§7.3.10 reads `N G R` past the first integer), so
 *  the bytes after it cannot change the value. */
function written(model: ValueModel, prefix: Uint8Array, suffix: Uint8Array, choices: Choices): Written {
  const before = choices.chance(50) ? latin1(separator(choices)) : new Uint8Array(0);
  const value = writeValue(model, choices);
  const after = latin1(`${choices.chance(50) ? separator(choices) : ""})`);
  const parts = [prefix, before, value, after, suffix];
  const bytes = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0));
  let at = 0;
  for (const part of parts) {
    bytes.set(part, at);
    at += part.length;
  }
  const offset = prefix.length;
  return { bytes, offset, end: offset + before.length + value.length };
}

const caseArb = fc.record({
  model: valueArb(true),
  prefix: fc.uint8Array({ maxLength: 8 }),
  suffix: fc.uint8Array({ maxLength: 8 }),
  draws: drawsArb,
});

interface Damage {
  readonly cut: number;
  readonly writes: readonly { readonly at: number; readonly byte: number }[];
}

/** A cut inside the value (a value left unfinished), then up to three bytes overwritten anywhere. */
const damageArb: fc.Arbitrary<Damage> = fc.record({
  cut: fc.nat(),
  writes: fc.array(fc.record({ at: fc.nat(), byte: fc.integer({ min: 0, max: 255 }) }), { maxLength: 3 }),
});

function damaged({ bytes, offset, end }: Written, damage: Damage): Uint8Array {
  const out = bytes.slice(0, offset + 1 + (damage.cut % Math.max(1, end - offset)));
  for (const { at, byte } of damage.writes) out[at % out.length] = byte;
  return out;
}

describe("parseValue - generated values", () => {
  it("reads back the value written, and ends where it ends (7.2, 7.3)", () => {
    fc.assert(
      fc.property(caseArb, ({ model, prefix, suffix, draws }) => {
        const { bytes, offset, end } = written(model, prefix, suffix, new Choices(draws));
        const parsed = parseValue(bytes, offset);
        expect(parsed.value).toEqual(expectedValue(model));
        expect(parsed.end, "end of the value").toBe(end);
      }),
      params(300),
    );
  });

  it("counts the nodes the generator made", () => {
    fc.assert(
      fc.property(caseArb, ({ model, prefix, suffix, draws }) => {
        const { bytes, offset } = written(model, prefix, suffix, new Choices(draws));
        expect(parseValue(bytes, offset).nodes).toBe(valueNodes(model));
      }),
      params(300),
    );
  });

  it("cut short or overwritten, gives a value or a refusal of ours, never a raw error", () => {
    let read = 0;
    let trials = 0;
    fc.assert(
      fc.property(caseArb, damageArb, ({ model, prefix, suffix, draws }, damage) => {
        const bytes = damaged(written(model, prefix, suffix, new Choices(draws)), damage);
        trials += 1;
        try {
          parseValue(bytes, prefix.length);
          read += 1;
        } catch (error) {
          expect(error, "a refusal of ours, never a raw error").toBeInstanceOf(PdfObjectsRefusal);
        }
      }),
      params(300),
    );
    // Both branches must be exercised, or the property sees only one side. Measured on 24/11/2026 with this seed:
    // 34 of 300 damaged values still read.
    expect(read, "damaged values that still read").toBeGreaterThan(0);
    expect(read, "damaged values refused").toBeLessThan(trials);
  });
});
